python3 - <<'EOF'
import re, zipfile, shutil
import defusedxml.minidom

SRC = "quarterly_report.docx"
TMP = "quarterly_report.new.docx"

HEADLINE_RE = re.compile(r"^[A-Z0-9][A-Z0-9 &()\-]*$")
AFTER_U = {"highlight","effect","bdr","shd","fitText","vertAlign",
           "rtl","cs","em","lang","eastAsianLayout","specVanish","oMath"}

def local_name(tag):
    return tag.split("}")[-1] if "}" in tag else tag

def insert_underline(rPr):
    for child in list(rPr.childNodes):
        if child.nodeType == child.ELEMENT_NODE and local_name(child.tagName) == "u":
            rPr.removeChild(child)
    doc = rPr.ownerDocument
    u = doc.createElement("w:u")
    u.setAttribute("w:val", "single")
    insert_after = None
    for child in rPr.childNodes:
        if child.nodeType != child.ELEMENT_NODE:
            continue
        if local_name(child.tagName) in AFTER_U:
            break
        insert_after = child
    if insert_after is None:
        rPr.insertBefore(u, rPr.firstChild)
    else:
        rPr.insertBefore(u, insert_after.nextSibling)

def paragraph_text(p):
    return "".join(t.firstChild.nodeValue for t in p.getElementsByTagName("w:t") if t.firstChild)

with zipfile.ZipFile(SRC, "r") as z:
    names = z.namelist()
    data = {n: z.read(n) for n in names}

dom = defusedxml.minidom.parseString(data["word/document.xml"].decode("utf-8"))
body = dom.getElementsByTagName("w:body")[0]
changed = []
for p in body.getElementsByTagName("w:p"):
    text = paragraph_text(p).strip()
    if text and HEADLINE_RE.match(text):
        for r in p.getElementsByTagName("w:r"):
            rPrs = r.getElementsByTagName("w:rPr")
            if rPrs:
                insert_underline(rPrs[0])
            else:
                rPr = dom.createElement("w:rPr")
                r.insertBefore(rPr, r.firstChild)
                insert_underline(rPr)
        changed.append(text)

new_xml = dom.toxml(encoding="UTF-8")

with zipfile.ZipFile(TMP, "w", zipfile.ZIP_DEFLATED) as z:
    for n in names:
        z.writestr(n, new_xml if n == "word/document.xml" else data[n])

shutil.move(TMP, SRC)
print("Underlined %d headlines:" % len(changed))
for c in changed:
    print("  -", c)
EOF
